CREATE TYPE "DocumentProcessingStatus" AS ENUM ('uploaded','scanning','extracting','parsed','needs_review','failed');
CREATE TYPE "DuplicateClassification" AS ENUM ('same_candidate','possible_duplicate','distinct');
CREATE TABLE "candidates" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"display_name" TEXT NOT NULL,"headline" TEXT,"location" TEXT,"profile_status" TEXT NOT NULL DEFAULT 'unreviewed',"merged_into_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "candidates_organization_id_created_at_idx" ON "candidates"("organization_id","created_at");
CREATE TABLE "ingestion_runs" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"position_id" TEXT,"source_type" TEXT NOT NULL,"status" TEXT NOT NULL,"total_count" INTEGER NOT NULL,"completed_count" INTEGER NOT NULL DEFAULT 0,"failed_count" INTEGER NOT NULL DEFAULT 0,"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ingestion_runs_organization_id_created_at_idx" ON "ingestion_runs"("organization_id","created_at");
CREATE TABLE "candidate_sources" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_id" TEXT REFERENCES "candidates"("id"),"ingestion_run_id" TEXT NOT NULL REFERENCES "ingestion_runs"("id") ON DELETE CASCADE,"source_type" TEXT NOT NULL,"permission_method" TEXT NOT NULL,"status" "DocumentProcessingStatus" NOT NULL DEFAULT 'uploaded',"source_label" TEXT NOT NULL,"imported_by_id" TEXT NOT NULL,"imported_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"warnings" JSONB NOT NULL DEFAULT '[]');
CREATE INDEX "candidate_sources_organization_id_candidate_id_idx" ON "candidate_sources"("organization_id","candidate_id");
CREATE TABLE "candidate_documents" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"source_id" TEXT NOT NULL UNIQUE REFERENCES "candidate_sources"("id") ON DELETE CASCADE,"storage_key" TEXT NOT NULL,"original_filename" TEXT NOT NULL,"media_type" TEXT NOT NULL,"byte_size" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"page_count" INTEGER,"malware_scan_status" TEXT NOT NULL,"pdf_type" TEXT,"parsed_text_markdown" TEXT,"pages_needing_ocr" JSONB NOT NULL DEFAULT '[]',"extractor" TEXT,"extractor_version" TEXT,"extraction_confidence" DOUBLE PRECISION,"processing_time_ms" INTEGER,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organization_id","checksum"));
CREATE TABLE "candidate_identities" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"candidate_id" TEXT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,"identity_type" TEXT NOT NULL,"normalized_value" TEXT,"value_fingerprint" TEXT NOT NULL,"raw_value_encrypted" TEXT,"verified" BOOLEAN NOT NULL DEFAULT FALSE,"source_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organization_id","identity_type","value_fingerprint"));
CREATE INDEX "candidate_identities_organization_id_candidate_id_idx" ON "candidate_identities"("organization_id","candidate_id");
CREATE TABLE "external_profile_links" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"candidate_id" TEXT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,"source_id" TEXT NOT NULL,"provider" TEXT NOT NULL,"profile_url" TEXT NOT NULL,"external_id" TEXT,"retrieval_method" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "external_profile_links_organization_id_candidate_id_idx" ON "external_profile_links"("organization_id","candidate_id");
CREATE TABLE "applications" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"candidate_id" TEXT NOT NULL REFERENCES "candidates"("id") ON DELETE CASCADE,"position_id" TEXT NOT NULL,"stage" TEXT NOT NULL DEFAULT 'applied',"created_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organization_id","candidate_id","position_id"));
CREATE INDEX "applications_organization_id_position_id_idx" ON "applications"("organization_id","position_id");
CREATE TABLE "duplicate_reviews" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL,"candidate_id" TEXT NOT NULL,"possible_candidate_id" TEXT NOT NULL,"classification" "DuplicateClassification" NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"signals" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"resolved_by_id" TEXT,"resolved_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "duplicate_reviews_organization_id_status_idx" ON "duplicate_reviews"("organization_id","status");
